BOOL CMyMainShowWnd::StartWork()
{
	TCHAR m_FileName[256] = _T("QQWry.dat");
	GetBinFilePath(m_FileName);
	WIN32_FILE_ATTRIBUTE_DATA m_Data = {0};
	if(!GetFileAttributesEx(m_FileName, GetFileExInfoStandard, &m_Data))
	{
		//�鿴QQIP���ļ��Ƿ����
		DWORD nLen = 0;
		LPBYTE pData  = GetMyExeSource(_T("IPDATA"), _T("MOD"), nLen);
		if(pData != NULL)
		{
			WriteMyFile(m_FileName, pData, nLen);
		}
	}

	CString m_VerInfo;
	m_VerInfo.Format(_T("%016d"), PS_USER_ID);
	TCHAR m_Title[256] = {0};
	wsprintf(m_Title, _T("%s%s[%s]"), PS_TITLE, _T(PS_VER_INFO), m_VerInfo.Right(4));
	SetWindowText(m_Title);
	pMainWnd->ResizeView();
	return TRUE;
}

LRESULT CMyMainShowWnd::OnIconInfo(WPARAM wParam,LPARAM lParam)
{
	switch(lParam)
	{
		case WM_LBUTTONDBLCLK :
			{
				SetForegroundWindow();
				ShowWindow(SW_SHOWMAXIMIZED);
				BringWindowToTop();
				return TRUE;
			}

		case WM_RBUTTONUP :
			{
				CPoint m_point;
				CMenu m_menu;
				m_menu.LoadMenu(IDR_MENU_ICON);
				GetCursorPos(&m_point);
				SetForegroundWindow(); 
				CXTPCommandBars::TrackPopupMenu(m_menu.GetSubMenu(0), TPM_RIGHTBUTTON, m_point.x, m_point.y, this);
				m_menu.DestroyMenu();	
			}
	}
	return TRUE;
}

