{
    CWnd* pActive = GetActiveView();
    if (pActive != nullptr)
    {
        CPcShareNextView* pView = DYNAMIC_DOWNCAST(CPcShareNextView, pActive);
        if (pView != nullptr)
        {
            CWnd* pPane = pView->GetDlgItem(AFX_IDW_PANE_FIRST + 1);
            if (pPane != nullptr)
            {
                CListView* pListView = DYNAMIC_DOWNCAST(CListView, CWnd::FromHandle(pPane->GetSafeHwnd()));
                if (pListView != nullptr)
                {
                    pListView->GetListCtrl().DeleteAllItems();
                    pListView->GetListCtrl().InsertItem(0, _T("Logs cleared"));
                    pListView->GetListCtrl().SetItemText(0, 1, _T("User requested clear"));
                }
            }
        }
    }
}
